<script setup>
import {ref,nextTick,watch} from 'vue';import {Head,Link,router,useForm} from '@inertiajs/vue3';import {date} from '../art';
const props=defineProps({overview:Object,filters:Object,cohorts:Array,subjects:Array,items:Object}),cohort=ref(props.filters.cohort||''),subject=ref(props.filters.subject||''),search=ref(props.filters.search||''),target=ref(null),assignmentPanel=ref(null);
const form=useForm({subject:'',topic:'',count:10,minutes:20,days:7});
function filter(){router.get('/admin/overview',{cohort:cohort.value||undefined,subject:subject.value||undefined,search:search.value||undefined})}
async function assign(u,s){target.value={user:u,subject:s};form.subject=s.subject;form.topic=s.topics[0]?.topic||'';form.count=Math.min(10,s.topics[0]?.available||s.available);form.clearErrors();await nextTick();assignmentPanel.value?.scrollIntoView({block:'start'});assignmentPanel.value?.focus()}
watch(()=>form.topic,()=>{if(target.value){const t=target.value.subject.topics.find(t=>t.topic===form.topic);form.count=Math.min(form.count,t?.available||target.value.subject.available)}});
</script>
<template><Head title="Cohort overview"/><h1>Head Chef · Cohort overview</h1><Link href="/admin">← Manage learners</Link><form class="filterbar panel" @submit.prevent="filter"><label>Cohort<select v-model="cohort"><option value="">All active students</option><option value="__unassigned__">Unassigned</option><option v-for="c in cohorts" :key="c">{{c}}</option></select></label><label>Question statistics subject<select v-model="subject"><option value="">All subjects</option><option v-for="s in subjects" :key="s">{{s}}</option></select></label><label>Question ID or topic<input v-model="search" maxlength="80"></label><button>Apply filters</button></form>
<div class="stat-grid"><div class="stat"><strong>{{overview.learners}}</strong><span>Active learner accounts</span></div><div class="stat"><strong>{{overview.active_seven_days}}</strong><span>Studied in the past 7 days</span></div><div class="stat"><strong>{{overview.first_total?Math.round(overview.first_correct/overview.first_total*100)+'%':'No data'}}</strong><span>{{overview.first_correct}} / {{overview.first_total}} first practice responses correct</span></div></div>
<section class="panel"><h2>Subject coverage and support</h2><p>Each cell shows correct / attempted first practice responses. Select a cell to assign focused practice. Assigned exams are excluded here. Coverage is against {{overview.available}} current distinct questions per learner.</p><div class="table-wrap" tabindex="0" aria-label="Scrollable cohort subject table"><table class="cohort-table"><thead><tr><th scope="col">Learner</th><th v-for="s in subjects" :key="s" scope="col">{{s}}</th></tr></thead><tbody><tr v-for="u in overview.rows" :key="u.id"><th scope="row"><Link :href="'/admin?student='+u.id">{{u.username}}</Link><small>{{u.attempted}} covered · {{date(u.last_active_at)}}</small></th><td v-for="s in u.subjects" :key="s.subject"><button :disabled="!s.available" @click="assign(u,s)" :class="{'needs-review':s.attempted>=5&&s.correct/s.attempted<.6}" :aria-label="u.username+', '+s.subject+': '+s.correct+' correct of '+s.attempted+' attempted. Assign focused practice.'">{{s.correct}} / {{s.attempted}}<small>{{s.covered}} / {{s.available}} covered</small></button></td></tr></tbody></table></div><p v-if="!overview.rows.length">No active students in this cohort.</p>
<details class="spaced"><summary>Learners who may benefit from a check-in</summary><p>Signals use seven days without activity or accuracy below 60% on at least five first practice responses. These are support prompts, not pass or fail predictions.</p><div v-for="u in overview.rows.filter(u=>u.support.length)" :key="u.id"><strong>{{u.username}}</strong><p>{{u.support.join(' · ')}}</p></div></details></section>
<section v-if="target" class="panel assignment-panel" ref="assignmentPanel" tabindex="-1" aria-live="polite"><h2>Focused practice for {{target.user.username}}</h2><form @submit.prevent="form.post('/admin/learners/'+target.user.id+'/practice',{preserveScroll:true,onSuccess:()=>target=null})"><p>{{form.subject}}</p><div class="form-grid"><label>Topic<select v-model="form.topic"><option value="">Whole subject</option><option v-for="t in target.subject.topics" :key="t.topic" :value="t.topic">{{t.topic}} · {{t.correct}} / {{t.total}} first answers correct</option></select></label><label>Questions<input v-model.number="form.count" type="number" min="1" max="50" required></label><label>Time limit (minutes)<input v-model.number="form.minutes" type="number" min="5" max="180" required></label><label>Open for (days)<input v-model.number="form.days" type="number" min="1" max="30" required></label></div><p>One attempt. Explanations appear after submission. The assignment appears on the learner's Counter.</p><button class="primary" :disabled="form.processing">Assign this practice</button><button type="button" @click="target=null">Cancel</button></form></section>
<section class="panel"><h2>Question observations</h2><p>First graded answer per learner and question version, including rated Memory Maki answers. Administrator activity and assigned exams are excluded. Counts show actual observations. Percentages require at least 20 learners as a display threshold; they do not validate difficulty or discrimination.</p><p v-if="!items.data.length">No matching graded responses yet.</p><article v-for="q in items.data" :key="q.id+':'+q.version" class="inset"><h3>{{q.id}} · version {{q.version}} · {{q.subject}}</h3><p>{{q.topic}} · {{q.correct}} / {{q.n}} correct <strong v-if="q.percent!==null">({{q.percent}}%)</strong></p><p>{{q.status}}</p><details><summary>Answer choices selected</summary><p v-for="o in q.options" :key="o.letter">{{o.letter}}. {{o.text}} · {{o.count}} {{o.key?'(key)':''}}</p></details><Link :href="'/admin/questions?search='+encodeURIComponent(q.id)">Review question</Link></article><div class="row"><Link v-if="items.prev_page_url" :href="items.prev_page_url">Previous</Link><span>Page {{items.current_page}} / {{items.last_page}}</span><Link v-if="items.next_page_url" :href="items.next_page_url">Next</Link></div></section></template>
